-- Torre por praça — tabela + RLS + seed (isolamento por login)
-- Executar UMA vez no SQL Editor do Supabase.
create table if not exists public.torre_snapshot(
  slug text primary key,
  nome text not null,
  dados jsonb not null,
  atualizado_em timestamptz not null default now()
);
grant select on public.torre_snapshot to authenticated;
grant insert,update on public.torre_snapshot to authenticated;
grant all on public.torre_snapshot to service_role;
alter table public.torre_snapshot enable row level security;
-- leitura: qualquer usuário LOGADO (dentista ou time). Sem login = nada.
drop policy if exists p_ts_read on public.torre_snapshot;
create policy p_ts_read on public.torre_snapshot for select to authenticated using (true);
-- escrita: só a conta do TIME (atualização da Torre).
drop policy if exists p_ts_write on public.torre_snapshot;
create policy p_ts_write on public.torre_snapshot for all to authenticated
  using (auth.jwt()->>'email' = 'equipe@ageodonto.com.br')
  with check (auth.jwt()->>'email' = 'equipe@ageodonto.com.br');

on conflict (slug) do update set nome=excluded.nome, dados=excluded.dados, atualizado_em=now();
